 template=template.replace('</section>\n<section id="analisis">','<details><summary>6 lembar native Revit R04</summary><p>M-R04-T-01 sampai M-R04-T-06 sudah ada pada model tersimpan. Garis dan teks native; anotasi tidak asosiatif. Ekspor berikut memperlihatkan isi lembar.</p><div class="downloads">'+native_links+'</div></details></section>\n<section id="analisis">',1)
 template=template.replace('<strong>8 X</strong><span>pengaku global dipertahankan</span>','<strong>10 X</strong><span>6 belakang · 2 sisi · 2 horizontal</span>').replace('PDF 4 lembar','PDF 6 lembar')
 template=template.replace('Model Revit native masih R03 karena koneksi Geopogo tidak tersedia; model web menampilkan usulan tangga R04.','Model tersimpan:165RHS,20diagonal,176bagian tangga3mm dan310bagian penutup2mm. Model web mengikuti komponen tersebut; penyangga tambahan dan sambungan pada RAB masih usulan.').replace('Data takikan beton belum tersedia. Blank dan gambar tangga memakai batas luar geometri; lakukan kupon tekuk dan ukur bidang khusus sebelum produksi.','Takikan tangga mengikuti outline IFC yang luasnya cocok dengan audit Revit. Penutup diberi celah3mm terhadap empat kolom beton; ukuran produksi mengikuti pengukuran dan kupon tekuk.')
 template=template.replace('Angka Rp123 pada toko cat tidak dipakai sebagai harga karena tampil sebagai placeholder; biaya cat memakai allowance yang jelas.','Harga cat dan hardware yang belum memiliki penawaran tertulis ditampilkan sebagai allowance.')
 (dist/'r04.html').write_text(template.replace('CARDS',cards).replace('SOURCES',sources),encoding='utf8')
 for name in ['style.css','app.js']:(dist/'assets/r04'/name).write_bytes((ROOT/('r04_'+name)).read_bytes())
 for page in ['index.html','tools.html']:
  p=dist/page;s=BeautifulSoup(p.read_text(encoding='utf8'),'html.parser')
  if page=='index.html':
   target=s.select_one('.project-links');target.insert(0,BeautifulSoup('<a href="r04.html">Tangga 3 mm · Detail & RAB R04 ↗</a>','html.parser'))
   s.select_one('#archive-menu nav').append(BeautifulSoup('<a href="r04.html">07 <span>Tangga & RAB R04</span>↗</a>','html.parser'))
  else:
   s.select_one('main').insert(0,BeautifulSoup('<p class="r04-banner"><a href="r04.html">R04 / Tangga pelat tekuk 3 mm · Gambar sambungan · RAB all-in ↗</a></p>','html.parser'))
   text=s.select_one('#tiga-d .lede')
   if text:text.string='R04:165RHS dan10setX;56bidang tangga3mm serta310bagian penutup2mm mengikuti model tersimpan. Dek tetap4mm. Matikan lapisan penutup untuk memeriksa rangka. Detail sambungan usulan tersedia di RAB dan gambar R04.'
   for el in s.select('.pitch-kicker span,.look-mast a,.look-footer p'):
    if el.string:el.string=el.string.replace('R03','R04')
   metrics=s.select('.pitch-metrics b')
   if metrics:metrics[-1].string='10 X'
   figure=s.select_one('.hero-drawing')
   if figure:
    figure.select_one('img')['src']='assets/r04/T-06.svg';figure.select_one('img')['alt']='Rencana10setX revisi R04'
    figure.select_one('figcaption').clear();figure.select_one('figcaption').append(BeautifulSoup('<span>R04 / POSISI BRACING</span><span>T-06</span>','html.parser'))
    for el,val in zip(figure.select('.hero-drawing-info b'),['165','80','20']):el.string=val
   stock=len(data['main_stock']);cost=stock*434500
   articles=s.select('#material .material-grid article')
   if len(articles)>1:
    articles[1].select('p')[-1].string=f'RAB R04 menggabungkan rangka165elemen,80kolom dan usulan penyangga tangga dalam{stock}stok6m. Buka RAB untuk dasar biaya.'
   budget=s.select_one('.pitch-budget-grid')
   if budget:
    budget.clear();budget.append(BeautifulSoup('<div><span>RAB TERPILIH / R04</span><b>Material + jasa</b><p>Pelat4/3/2mm, sambungan, cat, upah, logistik, overhead dan laba.</p></div><div><p>Rincian terbaru memakai ID model R04, harga satuan editable dan toggle jasa Rp6.000/kg.</p><a href="r04.html#rab">Buka RAB all-in R04 ↗</a></div>','html.parser'))
   old_gallery=s.select_one('.gallery-help')
   if old_gallery:old_gallery.clear();old_gallery.append(BeautifulSoup('Arsip R03 · LOD200. <a href="r04.html#gambar">Buka6lembar revisi R04: tangga, penutup dan posisi X ↗</a>','html.parser'))
   cut=s.select_one('#potong .lede')
   if cut:cut.string='Pola75stok pada lampiran ini adalah arsip R03. Rangka berubah menjadi165elemen; gunakan daftar potong R04 yang menghapus diagonal lama dan memasukkan penggantinya.'
   for sel in ['#boq .lede','#penawaran .lede']:
    el=s.select_one(sel)
    if el:el.clear();el.append(BeautifulSoup('Kalkulator kuantitas model. <a href="r04.html#rab">Gunakan RAB R04 untuk seluruh material, sambungan, upah, cat dan penawaran anggaran.</a>','html.parser'))
  p.write_text(str(s),encoding='utf8')
